import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

/**
 * Integrity check for the HapRay golden files.
 *
 * These fixtures are regenerated by `scripts/parity/hapray_reference.py`, not
 * by the test suite. This test only proves each file parses and still has the
 * top-level shape a later parity test will read, so a truncated or corrupted
 * fixture fails here rather than as an unrelated assertion much later.
 */
const FIXTURE_DIR = fileURLToPath(new URL('./fixtures/hapray/', import.meta.url));

function readFixture(name: string): unknown {
  return JSON.parse(readFileSync(join(FIXTURE_DIR, name), 'utf8'));
}

function objectKeys(value: unknown): string[] {
  expect(value).toBeTypeOf('object');
  expect(Array.isArray(value)).toBe(false);
  return Object.keys(value as Record<string, unknown>);
}

describe('HapRay parity fixtures', () => {
  it.each([
    ['fault-tree.emu_big.json', ['arkui', 'RS', 'av_codec', 'Audio']],
    ['fault-tree.real_device.json', ['arkui', 'RS', 'av_codec', 'Audio']],
    ['binder.emu_big.json', ['process_stats', 'thread_stats', 'interface_stats']],
    ['binder.real_device.json', []],
    [
      'components.components.json',
      ['details', 'max_component', 'recycled_builds', 'reusability_ratio', 'total_builds'],
    ],
    ['threads.emu_big.json', ['redundant_threads_summary', 'summary', 'below_threshold_patterns']],
    [
      'threads.real_device.json',
      ['redundant_threads_summary', 'summary', 'below_threshold_patterns'],
    ],
  ])('%s has the expected top-level keys', (file, expected) => {
    expect(objectKeys(readFixture(file)).sort()).toEqual([...expected].sort());
  });

  it.each(['thread-wakeup.emu_big.json', 'thread-wakeup.real_device.json'])(
    '%s is a non-empty wakeup result array',
    (file) => {
      const value = readFixture(file);
      expect(Array.isArray(value)).toBe(true);
      const rows = value as Array<Record<string, unknown>>;
      expect(rows.length).toBeGreaterThan(0);
      for (const row of rows) {
        expect(Object.keys(row)).toEqual(
          expect.arrayContaining([
            'thread_id',
            'thread_info',
            'total_instructions',
            'wakeup_threads',
          ]),
        );
      }
    },
  );
});
